INSERT INTO work_queue(id,task_type,payload,status,created_at) SELECT 'pending-structural-guard','metadata','{}','guard_failed',unixepoch() WHERE NOT ((SELECT COUNT(*) FROM c JOIN song_masters sm ON sm.id=c.master_id AND sm.album_id='pending-uploads' AND sm.title IS c.title_snapshot AND sm.track IS NULL AND sm.disc IS NULL JOIN song_instances si ON si.id=c.instance_id AND si.master_id=sm.id AND si.source_id='r2-local' AND si.source_type='original' AND si.missing=0 AND si.tag_scanned=1 AND lower(si.suffix)='wav' AND si.storage_object_id=c.object_id JOIN storage_entries se ON se.id=c.entry_id AND se.instance_id=si.id AND se.parent_id=c.parent_id AND se.path=c.path AND se.object_id=si.storage_object_id AND se.kind='file')=22 AND NOT EXISTS(SELECT 1 FROM albums WHERE id='al-17e41d5b4f') AND (SELECT COUNT(*) FROM song_masters sm JOIN song_instances si ON si.master_id=sm.id JOIN storage_entries se ON se.instance_id=si.id AND se.kind='file' WHERE se.path LIKE 'Distortion and Overdrive（2014）/%' AND si.missing=0)=22);
